import dao.ConnectionDB;
import ui.Menu;
import java.sql.Connection;

public class Main {
    public static void main(String[] args) {
        // Verificar que la conexión a BD funciona
        Connection conn = ConnectionDB.getConnection();
        if (conn == null) {
            System.out.println("❌ Error: No se puede conectar a la BD");
            return;
        }
        System.out.println("✓ Conexión a BD correcta\n");

        // Arrancar menú
        Menu menu = new Menu();
        menu.mostrarMenuPrincipal();
    }
}

package model.enums;

public enum Estil {
    ESPORTIVA("Esportiva"),
    CLASSICA("Clàssica"),
    GEL("Gel");

    private final String valor;

    Estil(String valor) {
        this.valor = valor;
    }

    public String getValor() {
        return valor;
    }

    public static Estil fromValor(String valor) {
        if (valor == null) return null;
        for (Estil e : values()) {
            if (e.valor.equalsIgnoreCase(valor.trim()) || e.name().equalsIgnoreCase(valor.trim())) {
                return e;
            }
        }
        return null;
    }
}

