package ui;

import java.util.Scanner;

public class Menu {
    private Scanner scanner;

    public Menu() {
        this.scanner = new Scanner(System.in);
    }

    public void mostrarMenuPrincipal() {
        boolean continuar = true;

        while (continuar) {
            System.out.println("\n========== PILLAM LTD - APP ESCALADA ==========");
            System.out.println("1. Gestionar Escoles");
            System.out.println("2. Gestionar Sectors");
            System.out.println("3. Gestionar Vies");
            System.out.println("4. Gestionar Escaladors");
            System.out.println("5. Búsquedas i Consultes");
            System.out.println("0. Salir");
            System.out.print("Selecciona una opció: ");

            int opcion = leerInt();

            switch (opcion) {
                case 1:
                    menuEscoles();
                    break;
                case 2:
                    menuSectors();
                    break;
                case 3:
                    menuVies();
                    break;
                case 4:
                    menuEscaladors();
                    break;
                case 5:
                    menuBusquedas();
                    break;
                case 0:
                    System.out.println("¡Fins aviat!");
                    continuar = false;
                    break;
                default:
                    System.out.println("Opció no vàlida");
            }
        }

        scanner.close();
    }

    private void menuEscoles() {
        System.out.println("\n--- GESTIONAR ESCOLES ---");
        System.out.println("1. Crear Escola");
        System.out.println("2. Consultar totes les Escoles");
        System.out.println("3. Modificar Escola");
        System.out.println("4. Eliminar Escola");
        System.out.println("0. Enrere");
        System.out.print("Opció: ");
        int opcion = leerInt();

        switch (opcion) {
            case 1:
                System.out.println("✓ Crear escola (en construcció)");
                break;
            case 2:
                System.out.println("✓ Llistar escoles (en construcció)");
                break;
            case 3:
                System.out.println("✓ Modificar escola (en construcció)");
                break;
            case 4:
                System.out.println("✓ Eliminar escola (en construcció)");
                break;
            case 0:
                break;
            default:
                System.out.println("Opció no vàlida");
        }
    }

    private void menuSectors() {
        System.out.println("\n--- GESTIONAR SECTORS ---");
        System.out.println("1. Crear Sector");
        System.out.println("2. Consultar tots els Sectors");
        System.out.println("3. Modificar Sector");
        System.out.println("4. Eliminar Sector");
        System.out.println("0. Enrere");
        System.out.print("Opció: ");
        int opcion = leerInt();

        switch (opcion) {
            case 1:
                System.out.println("✓ Crear sector (en construcció)");
                break;
            case 2:
                System.out.println("✓ Llistar sectors (en construcció)");
                break;
            case 3:
                System.out.println("✓ Modificar sector (en construcció)");
                break;
            case 4:
                System.out.println("✓ Eliminar sector (en construcció)");
                break;
            case 0:
                break;
            default:
                System.out.println("Opció no vàlida");
        }
    }

    private void menuVies() {
        System.out.println("\n--- GESTIONAR VIES ---");
        System.out.println("1. Crear Via (Esportiva/Clàssica/Gel)");
        System.out.println("2. Consultar totes les Vies");
        System.out.println("3. Modificar Via");
        System.out.println("4. Eliminar Via");
        System.out.println("0. Enrere");
        System.out.print("Opció: ");
        int opcion = leerInt();

        switch (opcion) {
            case 1:
                System.out.println("✓ Crear via (en construcció)");
                break;
            case 2:
                System.out.println("✓ Llistar vies (en construcció)");
                break;
            case 3:
                System.out.println("✓ Modificar via (en construcció)");
                break;
            case 4:
                System.out.println("✓ Eliminar via (en construcció)");
                break;
            case 0:
                break;
            default:
                System.out.println("Opció no vàlida");
        }
    }

    private void menuEscaladors() {
        System.out.println("\n--- GESTIONAR ESCALADORS ---");
        System.out.println("1. Crear Escalador");
        System.out.println("2. Consultar tots els Escaladors");
        System.out.println("3. Modificar Escalador");
        System.out.println("4. Eliminar Escalador");
        System.out.println("0. Enrere");
        System.out.print("Opció: ");
        int opcion = leerInt();

        switch (opcion) {
            case 1:
                System.out.println("✓ Crear escalador (en construcció)");
                break;
            case 2:
                System.out.println("✓ Llistar escaladors (en construcció)");
                break;
            case 3:
                System.out.println("✓ Modificar escalador (en construcció)");
                break;
            case 4:
                System.out.println("✓ Eliminar escalador (en construcció)");
                break;
            case 0:
