                System.out.println("Opció no vàlida");
        }
    }

    private void menuBusquedas() {
        System.out.println("\n--- BÚSQUEDAS I CONSULTES ---");
        System.out.println("1. Vies disponibles d'una Escola");
        System.out.println("2. Vies per rang de dificultat");
        System.out.println("3. Vies per estat (Apte/Construcció/Tancada)");
        System.out.println("4. Escoles amb restriccions actives");
        System.out.println("5. Sectors amb més de X vies");
        System.out.println("6. Escaladors amb mateix nivell");
        System.out.println("7. Vies que han passat a 'Apte' recentment");
        System.out.println("8. Vies més llargues d'una Escola");
        System.out.println("0. Enrere");
        System.out.print("Opció: ");
        int opcion = leerInt();

        switch (opcion) {
            case 1:
                System.out.println("✓ Vies per escola (en construcció)");
                break;
            case 2:
                System.out.println("✓ Vies per rang (en construcció)");
                break;
            case 3:
                System.out.println("✓ Vies per estat (en construcció)");
                break;
            case 4:
                System.out.println("✓ Escoles amb restriccions (en construcció)");
                break;
            case 5:
                System.out.println("✓ Sectors amb X vies (en construcció)");
                break;
            case 6:
                System.out.println("✓ Escaladors per nivell (en construcció)");
                break;
            case 7:
                System.out.println("✓ Vies recents Apte (en construcció)");
                break;
            case 8:
                System.out.println("✓ Vies més llargues (en construcció)");
                break;
            case 0:
                break;
            default:
                System.out.println("Opció no vàlida");
        }
    }

    // Método auxiliar para leer int
    private int leerInt() {
        try {
            int valor = Integer.parseInt(scanner.nextLine());
            return valor;
        } catch (NumberFormatException e) {
            System.out.println("Error: Introdueix un número vàlid");
            return -1;
        }
    }

    // Método auxiliar para leer String
    public String leerString(String mensaje) {
        System.out.print(mensaje);
        return scanner.nextLine().trim();
    }

    // Método auxiliar para leer double
    public double leerDouble(String mensaje) {
        System.out.print(mensaje);
        try {
            return Double.parseDouble(scanner.nextLine());
        } catch (NumberFormatException e) {
            System.out.println("Error: Introdueix un número vàlid");
            return 0;
        }
    }
}
